    "hajjQiranData": MessageLookupByLibrary.simpleMessage(
      "[{\"title\":\"ما قبل اليوم الثامن\",\"subtitle\":\"أعمال الوصول للقارن\",\"actions\":[{\"name\":\"نية القران\",\"emoji\":\"🤲\",\"sections\":[{\"title\":\"الجمع في النية\",\"items\":[\"ينوي قائلاً: \\\"لبيك اللهم عمرة وحجاً\\\".\",\"لا يتحلل القارن من إحرامه مثل المُفرِد، بل يبقى مُحرِماً حتى يوم النحر.\"],\"type\":\"text\"}]},{\"name\":\"طواف القدوم والسعي\",\"emoji\":\"🕋\",\"sections\":[{\"title\":\"طواف وسعي\",\"items\":[\"يطوف ٧ أشواط للقدوم. وله أن يسعى ٧ أشواط سعياً يجزئه عن سعي الحج.\",\"يبقى على إحرامه بعد السعي، ولا يحلق ولا يقصر.\"],\"type\":\"text\"}]}]},{\"title\":\"اليوم الثامن\",\"subtitle\":\"يوم التروية - ٨ ذو الحجة\",\"actions\":[{\"name\":\"المبيت بمنى\",\"emoji\":\"🏕️\",\"sections\":[{\"title\":\"أعمال يوم التروية\",\"items\":[\"يتوجه الحاج (المفرد والقارن على إحرامهما، والمتمتع يُحرم من مكانه) إلى منى ضحى.\",\"الخروج إلى منى يوم التروية سنة وليس واجباً.\",\"يصلي فيها الظهر والعصر والمغرب والعشاء وفجر التاسع.\",\"تصلى الصلاة الرباعية ركعتين (قصراً) كل صلاة في وقتها (بدون جمع).\",\"يُكثر من التلبية والذكر والدعاء واستحضار عظمة الزمان.\"],\"type\":\"text\"}]}]},{\"title\":\"اليوم التاسع\",\"subtitle\":\"يوم عرفة - ٩ ذو الحجة\",\"actions\":[{\"name\":\"الوقوف بعرفة\",\"emoji\":\"⛰️\",\"sections\":[{\"title\":\"الركن الأعظم\",\"items\":[\"يتوجه الحاج من منى إلى عرفة بعد طلوع الشمس بهدوء وتلبية.\",\"يصلي الظهر والعصر ومعهما الإمام بمسجد نمرة أو في مخيمه (جمع تقديم وقصراً بأذان وإقامتين).\",\"يتفرغ الحاج تماماً للدعاء والذكر والتضرع، مستقبلاً القبلة، رافعاً يديه، ملحاً على الله حاجته، حتى غروب الشمس.\",\"لا يجوز الخروج من حدود عرفة قبل غروب الشمس.\"],\"type\":\"text\"},{\"title\":\"خير الدعاء دعاء عرفة\",\"items\":[\"خير ما قلت أنا والنبيون من قبلي: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.\"],\"type\":\"dua\"}]},{\"name\":\"المبيت بمزدلفة\",\"emoji\":\"🌙\",\"sections\":[{\"title\":\"النفور إلى مزدلفة\",\"items\":[\"بعد غروب الشمس ينفر الحاج إلى مزدلفة بسكينة ووقار ملبياً.\",\"يصلي في مزدلفة المغرب ثلاثاً والعشاء ركعتين (جمع تأخير) فور وصوله ولو في منتصف الليل.\",\"يبيت في مزدلفة حتى يصلي الفجر, ثم يقف عند المشعر الحرام (أو في مكانه) يدعو الله حتى يُسفر جداً.\",\"رخص النبي صلى الله عليه وسلم للضعفاء والنساء بالدفع من مزدلفة إلى منى بعد منتصف الليل.\"],\"type\":\"text\"}]}]},{\"title\":\"اليوم العاشر\",\"subtitle\":\"يوم النحر - العيد\",\"actions\":[{\"name\":\"رمي جمرة العقبة\",\"emoji\":\"🎯\",\"sections\":[{\"title\":\"الرمي\",\"items\":[\"يصل الحاج إلى منى يوم العيد، فيرمي جمرة العقبة الكبرى بـ ٧ حصيات متعاقبات.\",\"يكبر مع كل حصاة: (الله أكبر).\",\"يُقطع التلبية عند رمي أول حصاة من جمرة العقبة.\",\"يُفضل أن تكون الحصى بحجم حبة الحمص وتُجمع من مزدلفة أو منى.\"],\"type\":\"text\"}]},{\"name\":\"ذبح الهدي\",\"emoji\":\"🐑\",\"sections\":[{\"title\":\"أحكام الهدي\",\"items\":[\"المفرد: ليس عليه هدي.\",\"القارن والمتمتع: يجب عليهما ذبح الهدي (شاة، أو سبع بدنة، أو سبع بقرة).\",\"يجوز توكيل الجهات الرسمية (بنوك التنمية الإسلامية) بذبح الهدي عن الحاج.\"],\"type\":\"text\"}]},{\"name\":\"الحلق أو التقصير\",\"emoji\":\"✂️\",\"sections\":[{\"title\":\"التحلل الأول\",\"items\":[\"يحلق الرجل جميع شعر رأسه أو يقصره، والحلق أفضل لقوله ﷺ: (اللهم ارحم المحلقين).\",\"المرأة تجمع شعرها وتقص من أطرافه قدر أنملة.\",\"بذلك يحل للحاج التحلل الأول (يحل له كل شيء من محظورات الإحرام إلا النساء والجماع).\"],\"type\":\"text\"}]},{\"name\":\"طواف الإفاضة\",\"emoji\":\"🕋\",\"sections\":[{\"title\":\"الركن الثاني\",\"items\":[\"ينزل مكة ليطوف طواف الإفاضة (ركن لا يتم الحج إلا به).\",\"يطوف ٧ أشواط، وليس فيه رمل ولا اضطباع.\",\"بعد الطواف (والسعي لمن عليه سعي) يحل للحاج التحلل الأكبر الشامل لكل شيء بما فيه النساء.\"],\"type\":\"text\"}]},{\"name\":\"السعي لمن لم يسع\",\"emoji\":\"🚶\",\"sections\":[{\"title\":\"سعي الحج\",\"items\":[\"المفرد والقارن: إذا كانا قد سعيا بعد طواف القدوم، فلا سعي عليهما الآن.\",\"المتمتع: يجب عليه السعي (لأن سعيه الأول كان للعمرة وهذا للحج).\"],\"type\":\"text\"}]}]},{\"title\":\"أيام التشريق\",\"subtitle\":\"١١، ١٢، ١٣ ذو الحجة\",\"actions\":[{\"name\":\"رمي الجمرات الثلاث\",\"emoji\":\"🎯\",\"sections\":[{\"title\":\"أحكام الرمي في التشريق\",\"items\":[\"يرمي الحاج الجمرات الثلاث كل يوم بعد زوال الشمس (دخول وقت الظهر).\",\"يبدأ بالجمرة الصغرى (٧ حصيات)، ثم يتقدم ويدعو طويلاً.\",\"ثم الجمرة الوسطى (٧ حصيات)، ثم يتقدم ويدعو طويلاً.\",\"ثم جمرة العقبة الكبرى (٧ حصيات) وينصرف ولا يدعو بعدها.\"],\"type\":\"text\"}]},{\"name\":\"المبيت بمنى\",\"emoji\":\"🏕️\",\"sections\":[{\"title\":\"واجب المبيت\",\"items\":[\"المبيت بمنى ليالي أيام التشريق واجب.\",\"يجب على الحاج أن يقضي معظم الليل في منى.\",\"يجوز للحاج أن يتعجل فيغادر منى يوم ١٢ ذي الحجة شريطة أن ينفر قبل غروب الشمس.\"],\"type\":\"text\"}]}]},{\"title\":\"ختام المناسك\",\"subtitle\":\"المغادرة وطواف الوداع\",\"actions\":[{\"name\":\"طواف الوداع\",\"emoji\":\"🕋\",\"sections\":[{\"title\":\"آخر العهد بالبيت\",\"items\":[\"طواف الوداع واجب على كل حاج أراد مغادرة مكة عائداً لبلده.\",\"يكون طواف الوداع آخر شيء يفعله الحاج قبل سفره مباشرة.\",\"يطوف ٧ أشواط، بدون سعي، ولا رمل.\",\"يسقط طواف الوداع عن المرأة الحائض والنفساء.\"],\"type\":\"text\"}]}]}]",
    ),
